using DotBoxD.Codecs.MessagePack;
using DotBoxD.Services.Protocol;
using Xunit;

namespace DotBoxD.Services.Tests.Protocol.Compatibility;

/// <summary>Generated by the published 0.1.0-ci.5510 Services/MessagePack packages, not current source.</summary>
public sealed class PreviousPackageWireFixtureTests
{
    private const string RequestHex =
        "5B0000002A000000014B00000085A94D65737361676549642AAB536572766963654E616D65A443616C63AA4D6574686F644E" +
        "616D65A3416464AA496E7374616E63654964AA696E7374616E63652D37A753747265616D73C0010203";

    private const string ResponseHex =
        "460000002A000000023800000085A94D65737361676549642AA9497353756363657373C3AC4572726F724D657373616765C0" +
        "A94572726F7254797065C0A653747265616DC02A";

    private const string ErrorHex =
        "570000002A000000034A00000085A94D65737361676549642AA9497353756363657373C2AC4572726F724D657373616765A6" +
        "44656E696564A94572726F7254797065AC506F6C69637944656E696564A653747265616DC0";

    [Fact]
    public void Previous_request_is_readable_and_current_writer_preserves_its_exact_bytes()
    {
        var serializer = new MessagePackRpcSerializer();
        var previous = Convert.FromHexString(RequestHex);
        Assert.True(MessageFramer.TryReadFrame(previous, out var id, out var type, out var envelope, out var payload));
        Assert.Equal(42, id);
        Assert.Equal(MessageType.Request, type);
        var request = serializer.Deserialize<RpcRequest>(envelope);
        Assert.Equal("Calc", request.ServiceName);
        Assert.Equal("Add", request.MethodName);
        Assert.Equal("instance-7", request.InstanceId);
        Assert.Equal(new byte[] { 1, 2, 3 }, payload.ToArray());
        using var current = MessageFramer.FrameMessage(serializer, id, type, request, payload.Span);
        Assert.Equal(previous, current.Memory.ToArray());
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void Previous_response_and_error_remain_bidirectionally_byte_compatible(bool success)
    {
        var serializer = new MessagePackRpcSerializer();
        var previous = Convert.FromHexString(success ? ResponseHex : ErrorHex);
        Assert.True(MessageFramer.TryReadFrame(previous, out var id, out var type, out var envelope, out var payload));
        Assert.Equal(42, id);
        Assert.Equal(success ? MessageType.Response : MessageType.Error, type);
        var response = serializer.Deserialize<RpcResponse>(envelope);
        Assert.Equal(success, response.IsSuccess);
        Assert.Equal(success ? null : "Denied", response.ErrorMessage);
        Assert.Equal(success ? null : "PolicyDenied", response.ErrorType);
        Assert.Equal(success ? new byte[] { 42 } : [], payload.ToArray());
        using var current = MessageFramer.FrameMessage(serializer, id, type, response, payload.Span);
        Assert.Equal(previous, current.Memory.ToArray());
    }
}
